<script lang="ts">
import {onMount} from 'svelte';
import {beforeNavigate} from '$app/navigation';
beforeNavigate(navigation=>{if(navigation.from&&busy)navigation.cancel();});
import {api} from '../../../lib/api';
import {session,loadSession} from '../../../lib/auth';
type Account={id:number;username:string;display_name:string;role:'administrator'|'librarian';enabled?:boolean;disabled?:boolean};
let accounts:Account[]=[];let username='';let displayName='';let role:'administrator'|'librarian'='librarian';let password='';let busy=false;let loading=true;let error='';let message='';
let editing:Account|null=null;let editName='';let editRole:'administrator'|'librarian'='librarian';let editDisabled=false;let editPassword='';
async function load(){try{accounts=(await api<{accounts:Account[]}>('/api/staff/accounts')).accounts;}catch(e){error=(e as Error).message;}finally{loading=false;}}
onMount(()=>{void load();});
function edit(account:Account){editing=account;editName=account.display_name;editRole=account.role;editDisabled=account.disabled??account.enabled===false;editPassword='';error='';message='';}
async function create(event:SubmitEvent){event.preventDefault();if(busy)return;busy=true;error='';message='';try{await api('/api/staff/accounts',{username,display_name:displayName,role,password});username='';displayName='';password='';role='librarian';await load();message='Staff account created. Share its credentials privately with that person.';}catch(e){error=(e as Error).message;}finally{busy=false;}}
async function save(event:SubmitEvent){event.preventDefault();if(!editing||busy)return;busy=true;error='';message='';try{await api(`/api/staff/accounts/${editing.id}`,{display_name:editName,role:editRole,disabled:editDisabled,...(editPassword?{password:editPassword}:{})},'PATCH');editing=null;editPassword='';await load();await loadSession(true);message='Staff account updated.';}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<svelte:head><title>Staff accounts · Home Library</title></svelte:head>
<h1>Staff accounts</h1><p>Librarians manage books, borrowers and lending. Administrators also manage staff accounts, backups, settings and updates.</p>
{#if error}<p role="alert" class="library-error">{error}</p>{/if}{#if message}<p role="status">{message}</p>{/if}
{#if loading}<p role="status">Loading staff accounts…</p>{:else}<ul class="accounts">{#each accounts as account}<li><div><strong>{account.display_name||account.username}</strong><span>{account.username} · {account.role}{account.disabled||account.enabled===false?' · Disabled':''}{account.id===$session?.user?.id?' · You':''}</span></div><button class="library-button secondary" disabled={busy} onclick={()=>edit(account)}>Edit account</button></li>{/each}</ul>{/if}
{#if editing}<section><h2>Edit {editing.username}</h2><form onsubmit={save}><label class="library-field">Display name<input bind:value={editName} required disabled={busy}/></label><label class="library-field">Role<select bind:value={editRole} disabled={busy}><option value="librarian">Librarian</option><option value="administrator">Administrator</option></select></label><label><input type="checkbox" bind:checked={editDisabled} disabled={busy}/> Disable sign-in</label><label class="library-field">Reset password (optional)<input type="password" bind:value={editPassword} autocomplete="new-password" minlength="12" disabled={busy}/><small>Leave blank to keep the existing password.</small></label><div class="library-actions"><button class="library-button" disabled={busy}>Save account</button><button type="button" class="library-button secondary" disabled={busy} onclick={()=>{editing=null;editPassword='';}}>Cancel</button></div></form></section>{/if}
<section><h2>Add a staff account</h2><form onsubmit={create}><label class="library-field">Username<input bind:value={username} autocomplete="off" required disabled={busy}/></label><label class="library-field">Display name<input bind:value={displayName} required disabled={busy}/></label><label class="library-field">Role<select bind:value={role} disabled={busy}><option value="librarian">Librarian</option><option value="administrator">Administrator</option></select></label><label class="library-field">Initial password<input type="password" bind:value={password} autocomplete="new-password" minlength="12" required disabled={busy}/><small>Use at least 12 characters.</small></label><button class="library-button" disabled={busy}>{busy?'Saving…':'Create account'}</button></form></section>
<style>.accounts{list-style:none;padding:0;display:grid;gap:.75rem;margin-block:1.5rem}.accounts li{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:1rem;border:1px solid var(--app-line)}.accounts li div{display:grid;gap:.3rem}.accounts span{color:var(--app-muted)}section{margin-block:2rem}form{max-width:32rem;display:grid;gap:1rem}</style>
